diff --git a/source/snapshot-internals.ts b/source/snapshot-internals.ts
new file mode 100644
index 0000000..4e77f9d
--- /dev/null
+++ b/source/snapshot-internals.ts
@@ -0,0 +1,37 @@
+import type {InternalsType} from './core/options.js';
+
+export const snapshotInternals = (internals: InternalsType): InternalsType => {
+	const {hooks, retry} = internals;
+
+	const result: InternalsType = {
+		...internals,
+		context: internals.context,
+		cacheOptions: {...internals.cacheOptions},
+		https: {...internals.https},
+		agent: {...internals.agent},
+		headers: {...internals.headers},
+		retry: {
+			...retry,
+			errorCodes: [...retry.errorCodes!],
+			methods: [...retry.methods!],
+			statusCodes: [...retry.statusCodes!],
+		},
+		timeout: {...internals.timeout},
+		hooks: {
+			init: [...hooks.init],
+			beforeRequest: [...hooks.beforeRequest],
+			beforeError: [...hooks.beforeError],
+			beforeRedirect: [...hooks.beforeRedirect],
+			beforeRetry: [...hooks.beforeRetry],
+			afterResponse: [...hooks.afterResponse],
+		},
+		searchParams: internals.searchParams ? new URLSearchParams(internals.searchParams as URLSearchParams) : undefined,
+		pagination: {...internals.pagination},
+	};
+
+	if (result.url !== undefined) {
+		result.prefixUrl = '';
+	}
+
+	return result;
+};
diff --git a/test/snapshot-internals.ts b/test/snapshot-internals.ts
new file mode 100644
index 0000000..31cfa6c
--- /dev/null
+++ b/test/snapshot-internals.ts
@@ -0,0 +1,46 @@
+import test from 'ava';
+import Options, {type InternalsType} from '../source/core/options.js';
+import {snapshotInternals} from '../source/snapshot-internals.js';
+
+test('snapshots options like a clone but shares context', t => {
+	const defaults = new Options({
+		context: {value: 'original'},
+		prefixUrl: 'https://example.com/',
+		searchParams: 'key=first&key=second',
+	});
+	const internals = defaults.toJSON();
+	const clone = new Options(undefined, undefined, defaults).toJSON();
+	const snapshot = snapshotInternals(internals);
+
+	t.deepEqual(snapshot, clone);
+	t.not(snapshot, internals);
+	t.is(snapshot.context, internals.context);
+	t.not(clone.context, internals.context);
+
+	for (const key of ['agent', 'cacheOptions', 'headers', 'hooks', 'https', 'pagination', 'retry', 'searchParams', 'timeout'] as const) {
+		t.not(snapshot[key], internals[key], key);
+	}
+
+	for (const key of ['errorCodes', 'methods', 'statusCodes'] as const) {
+		t.not(snapshot.retry[key], internals.retry[key], key);
+	}
+
+	for (const key of ['init', 'beforeRequest', 'beforeError', 'beforeRedirect', 'beforeRetry', 'afterResponse'] as const) {
+		t.not(snapshot.hooks[key], internals.hooks[key], key);
+	}
+});
+
+test('keeps an existing URL and clears the prefix', t => {
+	const internals = new Options('path', {prefixUrl: 'https://example.com/'}).toJSON();
+	const snapshot = snapshotInternals(internals);
+
+	t.is(snapshot.url, internals.url);
+	t.is(snapshot.prefixUrl, '');
+	t.is(snapshot.searchParams, undefined);
+	t.is(internals.prefixUrl, 'https://example.com/');
+});
+
+test('throws for missing or incomplete internals', t => {
+	t.throws(() => snapshotInternals(undefined as unknown as InternalsType), {instanceOf: TypeError});
+	t.throws(() => snapshotInternals({} as InternalsType), {instanceOf: TypeError});
+});
